/**
 * Scribe's own buttons plus any another extension has registered.
 *
 * 🚨 Every consumer of the button list must go through this, not
 * SCRIBE_BUTTONS. A registered button missing from the admin builder can't be
 * added to the toolbar; missing from `buttonsFor` it is dropped as an unknown
 * key even after it has been; and missing from the driver's active-state
 * signature its pressed state never refreshes. Three different ways for a
 * button to be registered and still not work.
 */
export function allButtons() {
  return [...SCRIBE_BUTTONS, ...registeredButtons()];
}

/** Whether this browser can do voice typing at all. */
export function speechSupported() {
  return typeof window !== 'undefined' && !!(window.SpeechRecognition || window.webkitSpeechRecognition);
}

/**
 * The toolbar this reader gets, as button keys: the phone arrangement on a
 * phone when the admin made one, the desktop one otherwise.
 *
 * An admin who has never touched the setting gets the defaults PLUS whatever
 * other extensions have registered.
 *
 * 🚨 Only on the default path. Once the toolbar has been arranged by hand
 * that arrangement is an explicit decision, and an extension installed later
 * must not silently push a button into it. The admin finds it in the
 * builder's palette instead — which is why anything registering a button
 * still has to work without it (see common/registry.ts).
 */
export function configuredToolbar() {
  const phone = app.screen() === 'phone' ? app.forum.attribute('scribeToolbarPhone') : null;
  const saved = phone ?? app.forum.attribute('scribeToolbar');
  return saved ?? [...DEFAULT_TOOLBAR, ...registeredButtons().map(b => b.key)];
}
export function buttonsFor(keys) {
  const byKey = new Map(allButtons().map(b => [b.key, b]));
  // Unknown keys are dropped rather than rendered blank — a setting saved by an
  // older version must not leave a dead control in the toolbar.
  return keys.map(k => byKey.get(k)).filter(b => !!b);
}
